from __future__ import annotations


def _ch(number, slug, question, kicker, title, subtitle, layout, minutes,
        summary, metrics, sections, quote, diagram, checklist, citations):
    """Build a chapter record using the companion publication schema."""
    return {
        "chapter_number": number, "slug": slug, "question_number": number,
        "question_prompt": question, "kicker": kicker, "title": title,
        "subtitle": subtitle, "layout_template": layout,
        "reading_time_minutes": minutes, "executive_summary": summary,
        "key_metrics": [{"label": label, "value": value, "note": note}
                        for label, value, note in metrics],
        "sections": sections, "pull_quote": quote, "diagram_id": diagram,
        "action_checklist": checklist, "statutory_citations": citations,
    }


